// Row types for the Departments & Services tables and views
// (migrations 317–320).
//
// src/types/database.ts is generated by `supabase gen types` and must not be
// edited by hand. Hub Backend can import these shapes until the generated
// file is regenerated after the migrations are applied.

export const SERVICE_AUDIENCES = ["roster", "point_leaders", "everyone"] as const;
export type ServiceAudience = (typeof SERVICE_AUDIENCES)[number];

export const SERVICE_ROLES = ["owner", "access", "moderator"] as const;
export type ServiceRole = (typeof SERVICE_ROLES)[number];

export const ROCK_STATUSES = ["on_track", "off_track", "complete"] as const;
export type RockStatus = (typeof ROCK_STATUSES)[number];

export const BUDGET_CURRENCIES = ["ZAR", "USD"] as const;
export type BudgetCurrency = (typeof BUDGET_CURRENCIES)[number];

/** A staff ministry that department pages treat as another home (317). */
export interface StaffMinistryAlias {
  id: string;
  /** The ministry being folded. The row itself is not deleted. */
  staff_ministry_id: string;
  /** The department home lookups should open. */
  resolves_to_id: string;
  reason: string;
  created_at: string;
}

/**
 * staff_ministry_resolution. One row per staff ministry.
 * is_folded is true when an alias row exists; home_* is the resolved home.
 */
export interface StaffMinistryResolution {
  id: string;
  slug: string;
  name: string;
  ministry_type: string;
  is_active: boolean;
  cluster: string | null;
  purpose: string | null;
  parent_id: string | null;
  home_id: string;
  home_slug: string;
  home_name: string;
  is_folded: boolean;
}

/** services. audience is who may use the service beyond ministry grants. */
export interface Service {
  service_key: string;
  label: string;
  admin_href: string;
  audience: ServiceAudience;
  created_at: string;
}

/**
 * service_owners. owner and access both grant use. moderator is the
 * leaders of that ministry. admin_href matches the parent service.
 */
export interface ServiceOwner {
  id: string;
  service_key: string;
  staff_ministry_id: string;
  role: ServiceRole;
  admin_href: string;
  created_at: string;
}

/**
 * ministry_service_access. Grants for a ministry after alias resolution,
 * so a folded ministry lists its home's grants.
 */
export interface MinistryServiceAccess {
  staff_ministry_id: string;
  ministry_slug: string;
  home_ministry_id: string;
  service_key: string;
  role: ServiceRole;
  admin_href: string;
  audience: ServiceAudience;
  service_label: string;
}

/** ministry_rocks. Quarterly EOS rock. Yearly OKRs stay on okr_objectives. */
export interface MinistryRock {
  id: string;
  staff_ministry_id: string;
  year: number;
  /** 1–4. */
  quarter: number;
  title: string;
  owner_user_id: string | null;
  status: RockStatus;
  due_date: string | null;
  /** Progress note. */
  notes: string | null;
  created_by: string | null;
  created_at: string;
  updated_at: string;
}

/**
 * leadership_ministry_rollup. One rock or one current-cycle OKR objective.
 * source is `rock` or `okr_objective`. objective_scope is null for a rock.
 */
export interface LeadershipMinistryRollup {
  staff_ministry_id: string;
  ministry_slug: string;
  ministry_name: string;
  ministry_type: string;
  ministry_is_active: boolean;
  source: "rock" | "okr_objective";
  source_id: string;
  title: string;
  /** Rock status, or `current` for an OKR objective on the current cycle. */
  status: string;
  objective_scope: string | null;
  owner_user_id: string | null;
  due_date: string | null;
  period_year: number;
  period_quarter: number | null;
  notes: string | null;
  updated_at: string;
}

/** department_budgets. One figure per ministry per year, in cents. */
export interface DepartmentBudget {
  id: string;
  staff_ministry_id: string;
  year: number;
  finance_project_id: string | null;
  amount_cents: number;
  currency: BudgetCurrency;
  notes: string | null;
  created_by: string | null;
  updated_by: string | null;
  created_at: string;
  updated_at: string;
}

/** Exact ministry-name ↔ finance-project-name link. Not a budget amount. */
export interface StaffMinistryFinanceProject {
  staff_ministry_id: string;
  finance_project_id: string;
  match_basis: "exact_name";
  created_at: string;
}
